class Solution { fun minimumMoves(grid:Array<IntArray>):Int{val n=grid.size;val queue=java.util.ArrayDeque<IntArray>();val seen=Array(n){Array(n){BooleanArray(2)}};fun add(r:Int,c:Int,orientation:Int,distance:Int){if(!seen[r][c][orientation]){seen[r][c][orientation]=true;queue.addLast(intArrayOf(r,c,orientation,distance))}};add(0,0,0,0);while(queue.isNotEmpty()){val state=queue.removeFirst();val r=state[0];val c=state[1];val orientation=state[2];val distance=state[3];if(r==n-1&&c==n-2&&orientation==0)return distance;if(orientation==0){if(c+2<n&&grid[r][c+2]==0)add(r,c+1,0,distance+1);if(r+1<n&&grid[r+1][c]==0&&grid[r+1][c+1]==0){add(r+1,c,0,distance+1);add(r,c,1,distance+1)}}else{if(r+2<n&&grid[r+2][c]==0)add(r+1,c,1,distance+1);if(c+1<n&&grid[r][c+1]==0&&grid[r+1][c+1]==0){add(r,c+1,1,distance+1);add(r,c,0,distance+1)}}};return -1} }
